/bin/bash -lc "python - <<'PY'
import sim,mujoco
s=sim.Sim()
print('bodies:')
for i in range(s.model.nbody):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if name is not None:
        print(i,name)
print('joints:')
for i in range(s.model.njnt):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_JOINT,i)
    if name is not None:
        print(i,name,'qposadr',int(s.model.jnt_qposadr[i]),'dofadr',int(s.model.jnt_dofadr[i]))
print('geoms:')
for i in range(s.model.ngeom):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,i)
    if name is not None:
        print(i,name,'body',int(s.model.geom_bodyid[i]))
print('actuator count',s.model.nu)
for i in range(s.model.nu):
    print('act',i, s.actuator_names()[i])
print('qpos0',s.data.qpos)
print('xpos of relevant bodies:')
for i in range(s.model.nbody):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if name in ['panda_link0','panda_link1','panda_link2','panda_link3','panda_link4','panda_link5','panda_link6','panda_link7','left_finger','right_finger','panda_hand','panda_hand_tcp','panda_hand_joint']:
        print(name,i,s.data.xpos[i],s.data.xquat[i])
print('cup xquat',s.data.xquat[s.cup_body_id], 'cup body id',s.cup_body_id)
PY"

