    for gid in range(s.model.ngeom):
        if s.model.geom_bodyid[gid]==bid:
            gname = mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,gid)
            print(name,'geom id',gid,'name',gname,'pos',s.data.geom_xpos[gid],'size',s.model.geom_size[gid])
